mapper.select:
SELECT rw.risk_warning_id, rw.risk_warning_number, rw.company_id, rw.document_type, rw.document_category, rw.business_type, rw.creation_user_id, rw.is_release_warning, rw.is_presence_warning, rw.status, rw.data_class, rw.apply_date, rw.ref_risk_warning_id, rw.change_apply_desc, (select su.description from sys_user su where su.user_id=rw.created_by) creation_name, rwi.risk_warning_info_id, hbmrr.bp_id, hbmrr.bp_name, hbmrr.bp_code, hbmrr.bp_category, hbmrr.bp_category_description, hbmrr.bp_type, hbmrr.bp_type_description, hbmrr.bp_class, hbmrr.associated_division FROM plm_risk_warning rw LEFT JOIN plm_risk_warning_info rwi ON rw.risk_warning_id = rwi.risk_warning_id LEFT JOIN ( SELECT hbm.bp_id, hbm.bp_name, hbm.bp_code, hbm.bp_class, hbm.associated_division, hbmrr.bp_category, hbmrr.bp_type, hbc.description AS bp_category_description, hbt.description AS bp_type_description FROM hls_bp_master hbm LEFT JOIN ( SELECT mr.bp_id, mr.bp_category, mr.bp_type FROM ( SELECT
IF ( @p = hbmr.bp_id, @rank := @rank + 1 ,@rank := 1 ) AS RN, @p := hbmr.bp_id as rank1, hbmr.bp_id, hbmr.bp_category, hbmr.bp_type FROM hls_bp_master_role hbmr,(SELECT @p := NULL ,@rank := 0) r) mr WHERE RN = 1 ) hbmrr ON hbm.bp_id = hbmrr.bp_id LEFT JOIN hls_bp_category hbc ON hbmrr.bp_category = hbc.bp_category LEFT JOIN hls_bp_type hbt ON hbmrr.bp_type = hbt.bp_type ) hbmrr ON rw.bp_id = hbmrr.bp_id
hbmrr.bp_type = rw.bp_type
AND rw.risk_warning_id = #{riskWarningId}
AND rw.data_class='NORMAL'
AND rw.is_release_warning = #{isReleaseWarning}
AND rw.is_presence_warning = #{isPresenceWarning}
AND rw.company_id = #{companyId}
AND rw.status = #{status}
AND rw.data_class=#{dataClass}
AND rw.ref_risk_warning_id = #{refRiskWarningId}
AND rwi.change_iq = #{changeIq}

SELECT DISTINCT rw.CREATION_DATE AS warningStartDateS, AHP.END_TIME_ AS warningEndDateS, rw.risk_warning_id, rw.status, rw.is_release_warning, rw.is_presence_warning, rwi.risk_level, rwi.info_collection_method, hbmrr.bp_code, hbmrr.bp_name, hbmrr.bp_type_description, rw.creation_date FROM plm_risk_warning rw LEFT JOIN plm_risk_warning_info rwi ON rw.risk_warning_id = rwi.risk_warning_id LEFT JOIN ( SELECT hbm.bp_id, hbm.bp_name, hbm.bp_code, hbm.associated_division, hbmrr.bp_category, hbmrr.bp_type, hbc.description AS bp_category_description, hbt.description AS bp_type_description FROM hls_bp_master hbm LEFT JOIN ( SELECT hbmr.bp_id, hbmr.bp_category, hbmr.bp_type, min(hbmr.CREATION_DATE) FROM hls_bp_master_role hbmr GROUP BY hbmr.bp_id, hbmr.bp_category, hbmr.bp_type ) hbmrr ON hbm.bp_id = hbmrr.bp_id LEFT JOIN hls_bp_category hbc ON hbmrr.bp_category = hbc.bp_category LEFT JOIN hls_bp_type hbt ON hbmrr.bp_type = hbt.bp_type /* WHERE hbmrr.bp_category IN ( 'TENANT', 'MORTGAGOR', 'PLEDGOR', 'WARRANTOR', 'VENDER', 'SELLER', 'BUYER', 'EVALUATOR', 'OTHER_AGENCY', 'TENANT_SEC' )*/ ) hbmrr ON rw.bp_id = hbmrr.bp_id LEFT JOIN act_hi_procinst AHP ON rw.RISK_WARNING_ID= ahp.BUSINESS_KEY_ and (AHP.PROC_DEF_ID_ like 'RW_RISK_WARNING_WFL%' or AHP.PROC_DEF_ID_ like 'RW_RISK_WARNING_CHANGE_RELEASE_WFL%')
rw.company_id = #{companyId} AND hbmrr.bp_type = rw.bp_type AND rwi.change_iq = 'NORMAL' AND rw.data_class='NORMAL'
AND rw.risk_info_source like concat(concat('%',#{riskInfoSource}),'%')
AND (hbmrr.bp_name like concat(concat('%',#{bpName}),'%') OR hbmrr.bp_code like concat(concat('%',#{bpName}),'%'))
AND hbmrr.bp_code like concat(concat('%',#{bpName}),'%')
AND rw.status = #{status}
AND rwi.risk_level IN
#{item}
AND rw.is_release_warning IN
#{item}
AND rw.status IN
#{item}
AND to_char(rw.CREATION_DATE, 'YYYY-MM-DD') >= #{warningStartDateS,jdbcType=VARCHAR}
AND to_char(rw.CREATION_DATE,'YYYY-MM-DD') <= #{warningStartDateE,jdbcType=VARCHAR}
AND to_char(AHP.END_TIME_ ,'YYYY-MM-DD')>= #{warningEndDateS,jdbcType=VARCHAR}
AND to_char(AHP.END_TIME_ ,'YYYY-MM-DD')<= #{warningEndDateE,jdbcType=VARCHAR}

mapper.update:
update plm_risk_warning rw
 set rw.status = #{status},
 rw.SUBMIT_STATUS = #{submitStatus}
 where rw.risk_warning_id = #{riskWarningId}

update plm_risk_warning rw
 set rw.status = #{status},
 rw.SUBMIT_STATUS = #{submitStatus}
 where rw.risk_warning_number = #{riskWarningNumber}
